  "said.drive-google-drive.07c2964c": "Google Drive",
  "said.drive-google-drive.3ad31c62": "Google no longer accepts that connection. It may have been withdrawn from your Google account. Connect the drive again in Settings.",
  "said.drive-google-drive.7663fb48": "Google returned {status}.",
  "said.drive-google-drive.8761e449": "That folder is not there, or the account you connected cannot see it. A folder shared with you has to be opened in Drive at least once before it can be read.",
  "said.drive-google-drive.b744db3d": "Google refused that request. If it mentions a quota, the deployment's Drive API limit has been reached for now. {message}",
  "said.drive-google-drive.c0c95fa0": "Google did not return a way to renew the connection, which usually means this account had already granted it. Remove the platform's access in your Google account under Third-party apps, then connect again.",
  "said.drive-google-drive.dcf45956": "\"{name}\" is too large for Google to export in one piece. Download that one document from Drive as {extension} and add it on its own afterwards; everything else in the folder reads normally.",
  "said.drive-google-drive.e9fe6eee": "Read a folder straight from your Google Drive. Read-only: the platform can list and download, and cannot create, change or delete anything. You can withdraw it here or from your Google account at any time.",
  "said.drive-import.1f557235": "That folder has nothing in it the platform can read. Documents, spreadsheets and presentations are all read, including Google's own, so an empty result means the folder really is empty, or holds only things like Forms and shortcuts.",
  "said.drive-import.6977b553": "That folder comes to about {known} MB, which is more than can be read in one go. Choose the folder for one qualification rather than the drive it sits in.",
  "said.drive-import.bc65916e": "That folder holds {listedCount} files, which is more than can be read in one go. Choose the folder for one qualification rather than the drive it sits in.",
  "said.drive-index.adeba1a9": "You have not connected {label}. Connect it in Settings, and the folder can be read from there.",
  "said.drive-index.b3dd24ac": "That drive is not one the platform knows.",
  "said.drive-index.be999bc2": "This deployment cannot store a credential safely, so a drive cannot be connected. Whoever maintains it needs to set the sealing key.",
  "said.drive-index.f1db1389": "The stored {label} connection cannot be read. Connect it again in Settings.",
