  "said.enrolment-documents.6b935df0": "Document not found.",
  "said.enrolment-documents.98317f79": "Say why it was refused. The learner has to be told what to correct, and a refusal with no reason sends them back with nothing to act on.",
  "said.enrolment-documents.d417e6fa": "That copy was certified on {certifiedOn}, which is more than {CERTIFICATION_VALID_DAYS} days ago. A certified copy has to be current when it is supplied.",
  "said.enrolment-documents.e88ccb00": "That file was not accepted: {reason}",
