  "said.qualification-document-parse.0973d151": "No Exit Level Outcomes were found. Check this is the SAQA registration document rather than the curriculum.",
  "said.qualification-document-parse.25dc9567": "Criteria are listed for Exit Level Outcome {heading}, but no such outcome was found.",
  "said.qualification-document-parse.694845c9": "Exit Level Outcome {number} has no associated assessment criteria. The EISA is set against these, so please check the document.",
  "said.qualification-from-document.04da62cd": "It names {named} modules but sets out no topics or assessment criteria for any of them, which is what the Qualification Document looks like.",
  "said.qualification-from-document.0cde70e8": "This is a part qualification, but the full qualification it comes from is not on the platform yet. Import that one first: a part carries no curriculum of its own, so there is nothing to attach it to until the parent exists.",
  "said.qualification-from-document.3259ea8a": "It names {named} module but sets out no topics or assessment criteria for any of them, which is what the Qualification Document looks like.",
  "said.qualification-from-document.349cca01": "No Qualification Document was supplied, so there is no SAQA ID and no Exit Level Outcomes. Both can be added later, but the EISA is set against the outcomes.",
  "said.qualification-from-document.67ca0dc6": "\"{filename}\" looks like a scan: {pages} pages with almost no text in them. The platform cannot read it, so nothing can be indexed from it. Upload a digital copy.",
  "said.qualification-from-document.8853408d": "\"{filename}\" could not be read.",
  "said.qualification-from-document.96604097": "The Qualification Document was not filed: {message}",
  "said.qualification-from-document.b40e3a7a": "Created as a part of \"{title}\", taking {idsCount} of its {parentModulesCount} modules. Its curriculum is the parent's; nothing was copied, so a learner's work against a module counts once wherever they met it.",
  "said.qualification-from-document.b566090b": "Its Qualification Rules section named no modules, so nothing can be selected automatically. Choose them by hand once it exists.",
  "said.qualification-from-document.bd194675": "\"{title}\" already carries the code {curriculumCode}. Importing again here would replace its whole curriculum, and anything tagged to a criterion would go with it. Open that qualification instead.",
  "said.qualification-from-document.cc83d42b": "Its document says this is a part qualification, but the full qualification it comes from is not on the platform. Import that one first: this one shares its curriculum and has none of its own.",
  "said.qualification-from-document.ce45bc7a": "Its document says this is a skills programme, but the full qualification it comes from is not on the platform. Import that one first: this one shares its curriculum and has none of its own.",
  "said.qualification-from-document.d2e90a8b": "No curriculum modules were found in \"{filename}\". {named}Check it is the Curriculum Document rather than the Qualification Document or the Assessment Specification.",
  "said.qualification-from-document.de980f53": "No Assessment Specification was supplied. It is one of the three documents required before material can be authored against this qualification.",
  "said.qualification-preview.37a5ab3f": "Nothing has been built for this study unit yet, so a learner enrolled on the qualification would find it empty.",
